const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([141.780304, -27.667421]);
  const aoi = point.buffer(10000); // 10 km radius

  const date1 = '2025-04-06';
  const date2 = '2025-04-22';

  // 2. Data Acquisition - Sentinel-2
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
        .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  function getCollection(date, buffer) {
    return ee.ImageCollection('COPERNICUS/S2_HARMONIZED')
      .filterBounds(aoi)
      .filterDate(date, ee.Date(date).advance(buffer, 'day'))
      .map(maskS2clouds);
  }

  // Try to get images with increasing date windows
  let col1 = getCollection(date1, 1);
  let size1 = col1.size().getInfo();

  if (size1 === 0) {
    col1 = getCollection(date1, 3);
    size1 = col1.size().getInfo();
  }

  let col2 = getCollection(date2, 1);
  let size2 = col2.size().getInfo();

  if (size2 === 0) {
    col2 = getCollection(date2, 3);
    size2 = col2.size().getInfo();
  }

  console.log(`Date 1 (${date1}) Images: ${size1}`);
  console.log(`Date 2 (${date2}) Images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log('No images found for one or both dates.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing - Calculate NDVI
  function addNDVI(image) {
    const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
    return image.addBands(ndvi);
  }

  const img1 = col1.map(addNDVI).median();
  const img2 = col2.map(addNDVI).median();

  // 4. Check pixel counts
  const count1 = img1.select('NDVI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: aoi,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const count2 = img2.select('NDVI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: aoi,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`Date 1 Valid Pixels: ${count1}`);
  console.log(`Date 2 Valid Pixels: ${count2}`);

  if (count1 === 0 || count2 === 0) {
    console.log('No valid pixels after masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 5. Calculate mean NDVI
  const ndvi1 = img1.select('NDVI').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: aoi,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const ndvi2 = img2.select('NDVI').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: aoi,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  console.log(`NDVI ${date1}: ${ndvi1 !== null ? ndvi1.toFixed(3) : 'null'}`);
  console.log(`NDVI ${date2}: ${ndvi2 !== null ? ndvi2.toFixed(3) : 'null'}`);

  // 6. Validation & Final Answer
  if (ndvi1 === null || ndvi2 === null || isNaN(ndvi1) || isNaN(ndvi2)) {
    console.log('NDVI calculation returned invalid values.');
    console.log('<answer>C3</answer>');
    return;
  }

  if (ndvi1 < -1 || ndvi1 > 1 || ndvi2 < -1 || ndvi2 > 1) {
    console.log('NDVI values outside valid range [-1, 1].');
    console.log('<answer>C3</answer>');
    return;
  }

  console.log(`Difference (Apr 22 - Apr 6): ${(ndvi2 - ndvi1).toFixed(3)}`);

  if (ndvi2 > ndvi1) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
